源代码位于： <code>tkflu\render_manager.py</code> <pre><code>class RenderManager:
    _instance = None
    _dirty_widgets: Set[tk.Widget] = set()
    _animation_queue: List[Dict] = []
    _render_delay = 16  # ~60 FPS

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def mark_dirty(self, widget: tk.Widget):
        """标记组件需要重绘"""
        if widget not in self._dirty_widgets:
            self._dirty_widgets.add(widget)
            self._schedule_render()

    def queue_animation(
        self, widget: tk.Widget, animation_steps: List[Dict], step_time: int
    ):
        """添加动画到队列"""
        self._animation_queue.append(
            {
                "widget": widget,
                "steps": animation_steps,
                "current_step": 0,
                "step_time": step_time,
            }
        )
        self._schedule_render()

    @staticmethod
    def _root_for(widgets):
        """挑一个可用的 Tk 控件来挂 ``after`` 回调。"""
        if tk._default_root is not None:
            return tk._default_root
        for widget in widgets:
            try:
                return widget.winfo_toplevel()
            except Exception:
                continue
        return None

    def _pending(self) -&gt; bool:
        """是否已经有一个**真正还在排队**的重绘回调。

        旧实现用一个布尔量 ``_is_rendering`` 表示"已排程"。只要那次
        ``after`` 因为窗口被销毁 / 解释器消失而永远不执行，这个布尔量就
        永久卡在 ``True`` —— 之后所有的 ``mark_dirty`` 都会直接返回，
        集中式重绘**再也活不过来**，脏控件集合还会一直留着引用不放。
        这里改成问 Tk "那个 after 还在吗"。
        """
        handle = self.__dict__.get("_render_after")
        if handle is None:
            return False
        try:
            return bool(tk._default_root) and bool(
                tk._default_root.tk.call("after", "info", handle)
            )
        except Exception:
            return False

    def _schedule_render(self):
        """安排渲染任务"""
        if self._pending():
            return
        self.__dict__["_render_after"] = None
        root = self._root_for(self._dirty_widgets)
        if root is None:
            # 还没有任何可用的 Tk 解释器：等下一次 mark_dirty 再排程，
            # 而不是在这里抛异常。
            return
        try:
            self.__dict__["_render_after"] = root.after(
                self._render_delay, self._render_all
            )
        except Exception:
            self.__dict__["_render_after"] = None

    @staticmethod
    def _paint_order(widget):
        """按控件在窗口树里的深度排序（父控件先画，子控件后画）。

        ``tkinter`` 并未提供 ``winfo_zorder``；用 ``winfo_parent`` 的层级深度
        近似 Z 序，既稳定又不会抛异常。
        """
        depth = 0
        try:
            parent = widget.winfo_parent()
            seen = set()
            while parent and parent not in seen:
                seen.add(parent)
                depth += 1
                parent = widget.nametowidget(parent).winfo_parent()
        except Exception:
            return (0, "")
        return (depth, str(widget))

    def _render_all(self):
        """执行所有待处理的渲染任务"""
        self.__dict__["_render_after"] = None
        try:
            # 处理动画
            self._process_animations()

            # 处理脏组件
            if self._dirty_widgets:
                # 先取快照再遍历：_draw 过程里可能又有控件把自己标记为脏，
                # 那些留到下一轮，而不是在本轮里越滚越多。
                sorted_widgets = sorted(self._dirty_widgets, key=self._paint_order)
                for widget in sorted_widgets:
                    # 重绘过程中可能被销毁，需容错
                    try:
                        if hasattr(widget, "_draw_centralized"):
                            widget._draw_centralized()
                        elif hasattr(widget, "_draw"):
                            widget._draw()
                    except tk.TclError:
                        continue
                # 清空本轮的脏标记；这会同时抹掉遍历期间新加的标记，
                # 避免 FluButton._draw 结尾的 mark_dirty 造成 60FPS 空转。
                self._dirty_widgets.clear()
        finally:
            pass

        if self._animation_queue or self._dirty_widgets:
            self._schedule_render()

    def reset(self):
        """清空全部排队状态（销毁窗口 / 测试收尾时用）。"""
        self.__dict__["_render_after"] = None
        self._dirty_widgets.clear()
        self._animation_queue.clear()

    def _process_animations(self):
        """处理动画队列"""
        completed_animations = []

        for idx, anim in enumerate(self._animation_queue):
            widget = anim["widget"]
            steps = anim["steps"]
            current_step = anim["current_step"]

            if current_step &lt; len(steps):
                # 应用当前帧动画
                applier = getattr(widget, "_apply_animation_step", None)
                if applier is not None:
                    try:
                        applier(steps[current_step])
                    except tk.TclError:
                        pass
                anim["current_step"] += 1
            else:
                completed_animations.append(idx)

        # 移除完成的动画
        for idx in reversed(completed_animations):
            del self._animation_queue[idx]
